(function(){var d={"book": {"arcs": [], "entities": ["#tV6ZYqFoGLyDVPSyrCVU92t", "#tAgVdbgMLGDlLHNhDV2GPfN", "#tTHvq23nxz31IzPMzISJMli", "#tRawJw3bjpwBl1MGgwHThMN", "#tp76Vl6mTXBfynA57DUxzPy", "#thqEo9kFRhzbsU81hlfEVhc", "#tMhLXyRX3bWMDKiGwMvtZ3C", "#tXGhNyPKBpHwLvFDYnn1mMx", "#tONNoCznUzenDAB697NExiJ", "#tEdLjr68XPNe2sMwUYcEzDa", "#tVOkNr4qRfJk5DQSFvzN0lb"], "files": [{"container": "EXTENSION", "file": "troika-0.5-core-rules.ttrpg", "name": "Troika! Numinous Edition - The Rules"}], "id": "rules", "kind": "chapter", "label": "The Rules", "title": "Troika! Numinous Edition - The Rules"}, "entities": {"#t0CPALYKjP43ltBAUfQhkIr": {"book": "rules", "children": [], "choices": [], "desc": "If your opponent is not aware of your presence your attack is a Roll Under rather than a Roll Versus (1.2), they may not attack back, and you may add 2 to your Damage Roll.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#t0CPALYKjP43ltBAUfQhkIr", "key": "Hitting Someone Unawares", "name": "Hitting Someone Unawares", "parent": "#tMhLXyRX3bWMDKiGwMvtZ3C", "props": [{"name": "Number", "type": "STRING", "value": "7.3", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Hitting Someone Unawares", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#t0o1lttLoZrSkzAoLkYSO0Y": {"book": "rules", "children": [], "choices": [], "desc": "Armour takes up a number of item slots equal to twice its protective value. So Heavy Armour would use six slots, for example. See Section 10.2.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#t0o1lttLoZrSkzAoLkYSO0Y", "key": "Armour Encumbrance", "name": "Armour Encumbrance", "parent": "#tONNoCznUzenDAB697NExiJ", "props": [{"name": "Number", "type": "STRING", "value": "9.1", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Armour Encumbrance", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#t1v28ecTKupYM2RZKP2A5KQ": {"book": "rules", "children": [], "choices": [], "desc": "When reduced to 0 Stamina you are in danger of dying and must be healed in order to survive. If this is during an Initiative Round the next time the End of the Round Token is drawn you die. If this happens out of Initiative your friends have one opportunity to Heal you (restoring you to 1 Stamina) or else **you are dead.** **you are dead.**", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#t1v28ecTKupYM2RZKP2A5KQ", "key": "Running Out of Stamina", "name": "Running Out of Stamina", "parent": "#tRawJw3bjpwBl1MGgwHThMN", "props": [{"name": "Number", "type": "STRING", "value": "4.1", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Running Out of Stamina", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#t4MJMfAvNMSZKz7L5VbKaTD": {"book": "rules", "children": [], "choices": [], "desc": "You regain 2d6 Stamina if you sleep for 8 hours. You may also eat a Provision to regain 1d6 Stamina. A maximum of 3 Provisions per day provide healing benefits. There may be other forms of healing available at your GM’s discretion such as visiting bath houses or drinking potions. You may never have more Stamina than your starting total.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#t4MJMfAvNMSZKz7L5VbKaTD", "key": "Healing", "name": "Healing", "parent": "#tRawJw3bjpwBl1MGgwHThMN", "props": [{"name": "Number", "type": "STRING", "value": "4.2", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Healing", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#t6WwNNdSehWN64fD6n1e59i": {"book": "rules", "children": [], "choices": [], "desc": "If you roll a double 6 while attacking you strike a Mighty Blow, win the exchange, and inflict Double Damage (8.1). If both parties strike a Mighty Blow a spectacular clinch is formed, shattering both Weapons (in the case of beastly claws, tentacles, and so on they lose 1d6 Stamina instead).", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#t6WwNNdSehWN64fD6n1e59i", "key": "Mighty Blows", "name": "Mighty Blows", "parent": "#tMhLXyRX3bWMDKiGwMvtZ3C", "props": [{"name": "Number", "type": "STRING", "value": "7.4", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Mighty Blows", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#t8XyFUV2Bu5BdxKwKUPYfjl": {"book": "rules", "children": ["#tre5BJhC7N5xal6bKNrIDfG"], "choices": [], "desc": "Most Tests of Advanced Skills & Spells are Roll Under (12 & 14).", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#t8XyFUV2Bu5BdxKwKUPYfjl", "key": "Testing Advanced Skills & Spells", "name": "Testing Advanced Skills & Spells", "parent": "#tAgVdbgMLGDlLHNhDV2GPfN", "props": [{"name": "Number", "type": "STRING", "value": "2.1", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Testing Advanced Skills & Spells", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#t8sT6YvwXwA26nT9Ag04Ach": {"book": "rules", "children": [], "choices": [], "desc": "The random Turn length adds a degree of uncertainty where you never know how much time you have left. When actions are not taking place it represents hesitation, panic, or other incidental delays that can happen in a tense encounter where every second counts. The goblins have few Tokens because they are cowardly, not because they are slow; the dragon has many because it knows exactly what it wants, not because it is fast.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#t8sT6YvwXwA26nT9Ag04Ach", "key": "Rationale", "name": "Rationale", "parent": "#tp76Vl6mTXBfynA57DUxzPy", "props": [{"name": "Number", "type": "STRING", "value": "5.6", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Rationale", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#t9N2I7tsxT536igEoVRHKyz": {"book": "rules", "children": [], "choices": [], "desc": "The GM removes a Token from the Stack at random, the colour or design of which determines who holds the Initiative and takes a Turn. Consider giving a copy of their Token to each player so that everyone remembers which colour or design is theirs.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#t9N2I7tsxT536igEoVRHKyz", "key": "Using the Stack", "name": "Using the Stack", "parent": "#tp76Vl6mTXBfynA57DUxzPy", "props": [{"name": "Number", "type": "STRING", "value": "5.2", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Using the Stack", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tADhIjGn6shAfvrS7iNZWhu": {"book": "rules", "children": [], "choices": [], "desc": "It is entirely acceptable to use existing Weapons to provide the Damage matrix of roughly equivalent Exotic Weapons, such as counting a Rapier as a Sword for Damage purposes. This does not preclude the possibility of making specific matrices for your inventions.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tADhIjGn6shAfvrS7iNZWhu", "key": "Unusual Weapons", "name": "Unusual Weapons", "parent": "#tXGhNyPKBpHwLvFDYnn1mMx", "props": [{"name": "Number", "type": "STRING", "value": "8.3", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Unusual Weapons", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tAelk69HQVkihxImpKN5hoD": {"book": "rules", "children": [], "choices": [], "desc": "See Section 6.6. Note that having things near the top of your Inventory list is advantageous, so put things you’ll rarely need in a hurry, like Armour and money, near the bottom. Pack your bags well!", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tAelk69HQVkihxImpKN5hoD", "key": "Retrieving Items in a Hurry", "name": "Retrieving Items in a Hurry", "parent": "#tEdLjr68XPNe2sMwUYcEzDa", "props": [{"name": "Number", "type": "STRING", "value": "10.3", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Retrieving Items in a Hurry", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tAgVdbgMLGDlLHNhDV2GPfN": {"book": "rules", "children": ["#t8XyFUV2Bu5BdxKwKUPYfjl"], "choices": [], "desc": "Characters have a variety of Advanced Skills & Spells granted them by their Background. The number given in the Background plus their Skill is referred to as their Skill Total. Write this on the character sheet.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tAgVdbgMLGDlLHNhDV2GPfN", "key": "Advanced Skills & Spells", "name": "Advanced Skills & Spells", "parent": null, "props": [{"name": "Number", "type": "STRING", "value": "2", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Advanced Skills & Spells", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tAtrJBMLlzrxlkAbt26hmtb": {"book": "rules", "children": [], "choices": [], "desc": "Aim. On your Turn you may decide to take Aim with your ranged Weapon. To do so hold onto your Initiative Token. When your next Initiative Token is drawn you may roll twice and pick the best roll. If the End of the Round Token comes up and you haven’t used your Aim Token you may decide to hold onto it for the next Round.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tAtrJBMLlzrxlkAbt26hmtb", "key": "6.2.2", "name": "6.2.2", "parent": "#tYmlzHezIsyLzw3LwFmvZHi", "props": [{"name": "Number", "type": "STRING", "value": "6.2.2", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tCHoWNZtcmCFV7MB5C9KBuk": {"book": "rules", "children": [], "choices": [], "desc": "You may choose not to act when you hold Initiative. In that case put your Token back in the Stack.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tCHoWNZtcmCFV7MB5C9KBuk", "key": "Delay", "name": "Delay", "parent": "#thqEo9kFRhzbsU81hlfEVhc", "props": [{"name": "Number", "type": "STRING", "value": "6.4", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Delay", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tCOihmJIqn7Bb7juSZ0nIcQ": {"book": "rules", "children": [], "choices": [], "desc": "For every 8 hours rest you may regain 2d6 Luck. Luck may not exceed the starting value rolled at character creation save for exceptional situations. Running out of Luck inflicts no special penalty.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tCOihmJIqn7Bb7juSZ0nIcQ", "key": "Gaining and Losing Luck", "name": "Gaining and Losing Luck", "parent": "#tTHvq23nxz31IzPMzISJMli", "props": [{"name": "Number", "type": "STRING", "value": "3.2", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Gaining and Losing Luck", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tEdLjr68XPNe2sMwUYcEzDa": {"book": "rules", "children": ["#td3r7h832EinYF9lCXHzaFN", "#tLXQO8bGLvzahPP0NnnPy36", "#tAelk69HQVkihxImpKN5hoD", "#tXH8O2PZSmgG9cLrbnDQN7a"], "choices": [], "desc": "You may carry twelve things without issue. On your character sheet are twelve spaces to write in the things you’re lugging around with you.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tEdLjr68XPNe2sMwUYcEzDa", "key": "Encumbrance", "name": "Encumbrance", "parent": null, "props": [{"name": "Number", "type": "STRING", "value": "10", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Encumbrance", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tHaahA2NuBfgypvZHGd0Jd1": {"book": "rules", "children": [], "choices": [], "desc": "All enemies contribute a varying number of Initiative Tokens to the Initiative Stack according to their combined Initiative and share the same colour or design. When drawing an enemy Initiative Token the GM can declare that any enemy is acting, including an enemy who has acted previously this Round. Obviously this can be abused for mechanical gain on the GM’s part though that would be entirely to the detriment of the game and is discouraged. Apply Initiative Tokens as they make sense.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tHaahA2NuBfgypvZHGd0Jd1", "key": "Enemies", "name": "Enemies", "parent": "#tp76Vl6mTXBfynA57DUxzPy", "props": [{"name": "Number", "type": "STRING", "value": "5.5", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Enemies", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tJTqOdfo8T1KBFp6qdyKVyP": {"book": "rules", "children": ["#tdnsjXXmoUHbJoRVDoJme6a", "#tqOgp3wMSJRuGiR00eEyCZh", "#tiznrZZF7r4PK0hfUD6SW6m", "#tuq3Gag3c2OWVuQsQV1pM1s"], "choices": [], "desc": "During combat, or at other times where it is important to know who goes first, you need to assemble the Initiative Stack. To do this get a container and a selection of coloured dice or other convenient markers (consider cards, poker chips, and so on).", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tJTqOdfo8T1KBFp6qdyKVyP", "key": "Assemble the Stack", "name": "Assemble the Stack", "parent": "#tp76Vl6mTXBfynA57DUxzPy", "props": [{"name": "Number", "type": "STRING", "value": "5.1", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Assemble the Stack", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tLXQO8bGLvzahPP0NnnPy36": {"book": "rules", "children": [], "choices": [], "desc": "Large items are anything you need both hands to hold. They take up two slots in your inventory (we recommend writing them at a jaunty angle to fill up the space). Armour has its own rules.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tLXQO8bGLvzahPP0NnnPy36", "key": "Large Items", "name": "Large Items", "parent": "#tEdLjr68XPNe2sMwUYcEzDa", "props": [{"name": "Number", "type": "STRING", "value": "10.2", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Large Items", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tLpyhJ0fMEQrTcFhS81Yph4": {"book": "rules", "children": [], "choices": [], "desc": "If you ever go below 0 Stamina you are dead.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tLpyhJ0fMEQrTcFhS81Yph4", "key": "Negative Stamina", "name": "Negative Stamina", "parent": "#tRawJw3bjpwBl1MGgwHThMN", "props": [{"name": "Number", "type": "STRING", "value": "4.3", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Negative Stamina", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tMhLXyRX3bWMDKiGwMvtZ3C": {"book": "rules", "children": ["#tuZl4biz8GWTQEAC7fKPIXY", "#tgi5ZmozeCtBsJEZYvhiVYH", "#t0CPALYKjP43ltBAUfQhkIr", "#t6WwNNdSehWN64fD6n1e59i", "#tfkBZHhlf6AQxGrGsRaxLCF", "#tPrvSH0gmpV4gv44eYeF0hi", "#tzk4S4CWYL7177wKNptu87Z", "#tQ0cdGbkIay6khBUwLP2hX5", "#tmgNP1VdTufqKr7Y2wT6Xhg", "#ttkbj9neGS6PF9v9iKUNYYM", "#ta3LS2Gj5FivjZpmVVXwqaN"], "choices": [], "desc": null, "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tMhLXyRX3bWMDKiGwMvtZ3C", "key": "Other Concerns", "name": "Other Concerns", "parent": null, "props": [{"name": "Number", "type": "STRING", "value": "7", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Other Concerns", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tNvuTkq4PX9KIAdtG0ZG8Wq": {"book": "rules", "children": [], "choices": [], "desc": "Roll equal to or less than your current Luck score. Every time you Test your Luck, reduce your current Luck score by 1 regardless of whether the Test was successful or not. Testing your Luck is optional; you may always refuse to roll and instead accept your fate. The GM is not obliged to give you details of the consequences if they are not already obvious.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tNvuTkq4PX9KIAdtG0ZG8Wq", "key": "Testing your Luck", "name": "Testing your Luck", "parent": "#tTHvq23nxz31IzPMzISJMli", "props": [{"name": "Number", "type": "STRING", "value": "3.1", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Testing your Luck", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tODrM4gJZaT5y1yBldhg3Fy": {"book": "rules", "children": [], "choices": [], "desc": "Hired help that are willing to engage in combat each provide 1 Initiative Token to the Stack. Henchmen share a single colour Token and when a henchman Token is drawn the GM determines who acts and what they do. The GM should take the wishes of the players under advisement but act in the best interests of the henchman.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tODrM4gJZaT5y1yBldhg3Fy", "key": "Henchmen", "name": "Henchmen", "parent": "#tp76Vl6mTXBfynA57DUxzPy", "props": [{"name": "Number", "type": "STRING", "value": "5.4", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Henchmen", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tONNoCznUzenDAB697NExiJ": {"book": "rules", "children": ["#t0o1lttLoZrSkzAoLkYSO0Y"], "choices": [], "desc": "Armour offers a certain degree of protection to your soft and supple body. There are four levels of protection, vaguely defined, allowing you to assign whatever assortment of pots and pans you might be wearing to an appropriate level without too much bother. A target is considered to be Unarmoured, Lightly Armoured, Modestly Armoured, or Heavily Armoured. Each modifies Damage Rolls by 0, -1, -2 and -3 respectively, to a minimum of 1.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tONNoCznUzenDAB697NExiJ", "key": "Armour", "name": "Armour", "parent": null, "props": [{"name": "Number", "type": "STRING", "value": "9", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Armour", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tPrvSH0gmpV4gv44eYeF0hi": {"book": "rules", "children": [], "choices": [], "desc": "Shields reduce Damage Rolls by 1 to a minimum of 1.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tPrvSH0gmpV4gv44eYeF0hi", "key": "Shields", "name": "Shields", "parent": "#tMhLXyRX3bWMDKiGwMvtZ3C", "props": [{"name": "Number", "type": "STRING", "value": "7.6", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Shields", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tQ0cdGbkIay6khBUwLP2hX5": {"book": "rules", "children": ["#tkmHPSvcRsQP4CeIdGS92X7"], "choices": [], "desc": "When on the floor you suffer -2 to all physical rolls against those standing, including Damage Rolls, and must spend a Turn getting to your feet.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tQ0cdGbkIay6khBUwLP2hX5", "key": "Falling Over", "name": "Falling Over", "parent": "#tMhLXyRX3bWMDKiGwMvtZ3C", "props": [{"name": "Number", "type": "STRING", "value": "7.8", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Falling Over", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tR5pGMhUsua6OgkJgaklYDB": {"book": "rules", "children": [], "choices": [], "desc": "Each Spell has its own instructions on how it should be used but in general you need to spend a certain amount of Stamina and Roll Under or Roll Versus (for Spells that require you to touch an unwilling party, for instance) in order to create some kind of effect. Unless the Spell says otherwise it requires at least one hand free and the ability to speak. Roll on the Oops! Table if the result is a Fumble.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tR5pGMhUsua6OgkJgaklYDB", "key": "Cast a Spell", "name": "Cast a Spell", "parent": "#thqEo9kFRhzbsU81hlfEVhc", "props": [{"name": "Number", "type": "STRING", "value": "6.3", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Cast a Spell", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tRawJw3bjpwBl1MGgwHThMN": {"book": "rules", "children": ["#t1v28ecTKupYM2RZKP2A5KQ", "#t4MJMfAvNMSZKz7L5VbKaTD", "#tLpyhJ0fMEQrTcFhS81Yph4", "#toanDbyX8nTLpiPNLhJKjgd"], "choices": [], "desc": null, "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tRawJw3bjpwBl1MGgwHThMN", "key": "Stamina", "name": "Stamina", "parent": null, "props": [{"name": "Number", "type": "STRING", "value": "4", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Stamina", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tTHvq23nxz31IzPMzISJMli": {"book": "rules", "children": ["#tNvuTkq4PX9KIAdtG0ZG8Wq", "#tCOihmJIqn7Bb7juSZ0nIcQ", "#tgm9giBHXoDyzHbATMn2uAm", "#tZMnCZuuXiW4yyDHILqBwdP"], "choices": [], "desc": "Of all the numbers on your character sheet, Luck is likely to fluctuate the most. This number represents your character’s fortune and intuition, tested whenever fate swipes at them. When this happens the GM will ask you to Test your Luck or suffer the consequences.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tTHvq23nxz31IzPMzISJMli", "key": "Luck", "name": "Luck", "parent": null, "props": [{"name": "Number", "type": "STRING", "value": "3", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Luck", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tV6ZYqFoGLyDVPSyrCVU92t": {"book": "rules", "children": ["#tbXIAUx6rPdDQlc2IpQiYL1", "#tzfs8UbA9xaGFSk36Zq8Y4x"], "choices": [], "desc": "There is only one die type used in Troika!, that being the d6. This can be used as a d3, d6, d66, d666, and so on. To roll a d3 just roll a d6 and halve it, rounding up. To roll a d66, d666, or more just roll a d6 as many times, in order, as there are 6s. So a d66 would be a d6 followed by another d6 (e.g. I roll a 1 then roll a 4 thus making a roll of 14).\n\nTo do most actions you’ll be required to roll 2d6, adding them together, as a Roll Under or a Roll Versus.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tV6ZYqFoGLyDVPSyrCVU92t", "key": "Rolling the Dice", "name": "Rolling the Dice", "parent": null, "props": [{"name": "Number", "type": "STRING", "value": "1", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Rolling the Dice", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tV9P8EMQglefTupJK4PvN7j": {"book": "rules", "children": [], "choices": [], "desc": "Every action is assumed to have a bit of movement involved. Anything less than 4 metres is folded into whatever else you might be doing. If you wish to chase after someone or perform some other involved locomotion then just spend a Turn doing it.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tV9P8EMQglefTupJK4PvN7j", "key": "Move", "name": "Move", "parent": "#thqEo9kFRhzbsU81hlfEVhc", "props": [{"name": "Number", "type": "STRING", "value": "6.5", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Move", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tVOkNr4qRfJk5DQSFvzN0lb": {"book": "rules", "children": ["#tWUoAgsFLyVZK7mwTmAt0TH", "#tg4DsGe1ktxDuPHFXhaHNSS"], "choices": [], "desc": "Life is learning and you cannot experience it without growing in some way. Your characters bend and change in response to their environment. When you successfully Test an Advanced Skill or Spell you stand to learn from it. Put a tick next to it on your character sheet.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tVOkNr4qRfJk5DQSFvzN0lb", "key": "Getting Better", "name": "Getting Better", "parent": null, "props": [{"name": "Number", "type": "STRING", "value": "11", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Getting Better", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tWUoAgsFLyVZK7mwTmAt0TH": {"book": "rules", "children": ["#tZ0kY4Lq7Z1WJMYv4dmxfIv"], "choices": [], "desc": "The next time you have a chance to rest and reflect on your journey you may check to see what you have learned. Choose up to 3 Advanced Skills or Spells with a tick next to them. If you roll 2d6 **over**\n\nTotal (Advanced Skill/Spell + Skill) you may increase it by 1. When you have finished rolling, remove all ticks from your sheet.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tWUoAgsFLyVZK7mwTmAt0TH", "key": "How to Advance", "name": "How to Advance", "parent": "#tVOkNr4qRfJk5DQSFvzN0lb", "props": [{"name": "Number", "type": "STRING", "value": "11.1", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "How to Advance", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tXGhNyPKBpHwLvFDYnn1mMx": {"book": "rules", "children": ["#tvY0qW9xActloLVo5kOBhrv", "#tf2nXHlMCJjhMm33am9n0pH", "#tADhIjGn6shAfvrS7iNZWhu"], "choices": [], "desc": "When you win a Roll Versus an opponent in combat you inflict Damage. After successfully hitting someone roll d6 and consult the Damage Charts on the inside front cover of this book. Reference your Damage Roll across the top row and the Weapon down the side. The result is the Damage inflicted and is deducted from your opponent’s Stamina.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tXGhNyPKBpHwLvFDYnn1mMx", "key": "Damage", "name": "Damage", "parent": null, "props": [{"name": "Number", "type": "STRING", "value": "8", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Damage", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tXH8O2PZSmgG9cLrbnDQN7a": {"book": "rules", "children": ["#tshYslnHBIFqwvuUVarZsmJ"], "choices": [], "desc": "If you find yourself carrying more than 12 items you suffer -4 to all rolls due to the inconvenient weight. If you are carrying 18 items or more you suffer -4 to all rolls, you can hardly move, and you count as Unawares (7.3) for anyone wanting to stab you.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tXH8O2PZSmgG9cLrbnDQN7a", "key": "Overburdened", "name": "Overburdened", "parent": "#tEdLjr68XPNe2sMwUYcEzDa", "props": [{"name": "Number", "type": "STRING", "value": "10.4", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Overburdened", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tYmlzHezIsyLzw3LwFmvZHi": {"book": "rules", "children": ["#tnFNK0CoHKAXKJ3QZRntBQS", "#tAtrJBMLlzrxlkAbt26hmtb"], "choices": [], "desc": "Shooting an opponent is resolved by Rolling Versus their Skill or appropriate evasive Advanced Skill such as Shield or Dodge.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tYmlzHezIsyLzw3LwFmvZHi", "key": "Shoot Someone", "name": "Shoot Someone", "parent": "#thqEo9kFRhzbsU81hlfEVhc", "props": [{"name": "Number", "type": "STRING", "value": "6.2", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Shoot Someone", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tZ0kY4Lq7Z1WJMYv4dmxfIv": {"book": "rules", "children": [], "choices": [], "desc": "12+ Advanced Skill. When an Advanced Skill has reached 12 you must roll a 12 followed by another 12 to improve it further. There is no upper limit to an Advanced Skill.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tZ0kY4Lq7Z1WJMYv4dmxfIv", "key": "11.1.1", "name": "11.1.1", "parent": "#tWUoAgsFLyVZK7mwTmAt0TH", "props": [{"name": "Number", "type": "STRING", "value": "11.1.1", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tZMnCZuuXiW4yyDHILqBwdP": {"book": "rules", "children": [], "choices": [], "desc": "If you find your games are too fatal and that the turnover of characters is too much to bear the GM might optionally allow characters who have died to Test their Luck and, instead of dying, be incapacitated, wounded, or saved by some bizarre twist of fate.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tZMnCZuuXiW4yyDHILqBwdP", "key": "OPTIONAL: Luck Versus Death", "name": "OPTIONAL: Luck Versus Death", "parent": "#tTHvq23nxz31IzPMzISJMli", "props": [{"name": "Number", "type": "STRING", "value": "3.4", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "OPTIONAL: Luck Versus Death", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#ta3LS2Gj5FivjZpmVVXwqaN": {"book": "rules", "children": [], "choices": [], "desc": "There are two main units of time in the game: Turns and Rounds. A Turn is what someone does when they hold Initiative and is a few seconds long. A Round is the period between drawing successive End of the Round Tokens and is roughly equal to one minute.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#ta3LS2Gj5FivjZpmVVXwqaN", "key": "Time", "name": "Time", "parent": "#tMhLXyRX3bWMDKiGwMvtZ3C", "props": [{"name": "Number", "type": "STRING", "value": "7.11", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Time", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tbXIAUx6rPdDQlc2IpQiYL1": {"book": "rules", "children": [], "choices": [], "desc": "Rolling Under is the throwing of 2d6 with the intention of scoring equal to or under a number. This is mainly used in unopposed situations like climbing a wall or casting a Spell. Rolling two 6s always results in failure.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tbXIAUx6rPdDQlc2IpQiYL1", "key": "Roll Under", "name": "Roll Under", "parent": "#tV6ZYqFoGLyDVPSyrCVU92t", "props": [{"name": "Number", "type": "STRING", "value": "1.1", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Roll Under", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#td3r7h832EinYF9lCXHzaFN": {"book": "rules", "children": [], "choices": [], "desc": "Some items are of inconsequential individual weight, like arrows, and only ever take up one slot (unless you have an awful lot of them). What constitutes a lot is up to your group to decide.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#td3r7h832EinYF9lCXHzaFN", "key": "Small Items", "name": "Small Items", "parent": "#tEdLjr68XPNe2sMwUYcEzDa", "props": [{"name": "Number", "type": "STRING", "value": "10.1", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Small Items", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tdLHSrDDxqhgKWUgb6NEUAW": {"book": "rules", "children": [], "choices": [], "desc": "If an item is in your hands you may use it however you like (6.6).", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tdLHSrDDxqhgKWUgb6NEUAW", "key": "Use an Item", "name": "Use an Item", "parent": "#thqEo9kFRhzbsU81hlfEVhc", "props": [{"name": "Number", "type": "STRING", "value": "6.7", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Use an Item", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tdnsjXXmoUHbJoRVDoJme6a": {"book": "rules", "children": [], "choices": [], "desc": "Assign each character 2 Tokens of a single color.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tdnsjXXmoUHbJoRVDoJme6a", "key": "5.1.1", "name": "5.1.1", "parent": "#tJTqOdfo8T1KBFp6qdyKVyP", "props": [{"name": "Number", "type": "STRING", "value": "5.1.1", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#teAm2qHbWvT3WAenwFxKrdE": {"book": "rules", "children": [], "choices": [], "desc": "Fire, Poison, and Bleeding. Any ongoing debilitating effects should be treated similarly to Drowning. Unless you have a specific effect in mind have the victim lose 1d6 Stamina per Turn with it optionally becoming more severe unless they either pass a related Advanced Skill Test or successfully Test their Luck (or Skill for Enemies). Improvisation is strongly encouraged.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#teAm2qHbWvT3WAenwFxKrdE", "key": "7.9.1", "name": "7.9.1", "parent": "#tmgNP1VdTufqKr7Y2wT6Xhg", "props": [{"name": "Number", "type": "STRING", "value": "7.9.1", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tf2nXHlMCJjhMm33am9n0pH": {"book": "rules", "children": [], "choices": [], "desc": "All modifiers that add bonuses to Damage, unless otherwise specified, modify the roll of the die, not the actual Damage inflicted. So, for instance, I have +1 to my Damage Roll and roll a 5 on the Sword entry. Due to my bonus I am counted as having rolled a 6 and inflict 8 Damage instead of 6.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tf2nXHlMCJjhMm33am9n0pH", "key": "Damage Modifiers", "name": "Damage Modifiers", "parent": "#tXGhNyPKBpHwLvFDYnn1mMx", "props": [{"name": "Number", "type": "STRING", "value": "8.2", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Damage Modifiers", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tfkBZHhlf6AQxGrGsRaxLCF": {"book": "rules", "children": [], "choices": [], "desc": "A roll of double 1s in combat results in the roller losing the exchange and their opponent adding 1 to their Damage Roll. If both parties Fumble they each deal Damage to the other, adding 1 to their Damage Roll.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tfkBZHhlf6AQxGrGsRaxLCF", "key": "Fumbles", "name": "Fumbles", "parent": "#tMhLXyRX3bWMDKiGwMvtZ3C", "props": [{"name": "Number", "type": "STRING", "value": "7.5", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Fumbles", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tg4DsGe1ktxDuPHFXhaHNSS": {"book": "rules", "children": [], "choices": [], "desc": "It is also possible to improve your Advanced Skills or to learn new ones, though you must find someone willing to teach you. They must have a higher Skill Total (Advanced Skill/Spell + Skill) than you, and most likely require payment unless they are your fellow party member or already owe you a favour. Training takes 1 week plus 1 week per rank you already have in the Advanced Skill you are looking to improve. At the end of this time you get one chance at advancement. Failure means you just have to train harder. When learning new Advanced Skills you must Roll Under your Skill on 2d6 (precocious students are easier to teach) to gain your first point.\n\n**over** your current Skill", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tg4DsGe1ktxDuPHFXhaHNSS", "key": "Training and Learning New Advanced Skills", "name": "Training and Learning New Advanced Skills", "parent": "#tVOkNr4qRfJk5DQSFvzN0lb", "props": [{"name": "Number", "type": "STRING", "value": "11.2", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Training and Learning New Advanced Skills", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tgi5ZmozeCtBsJEZYvhiVYH": {"book": "rules", "children": [], "choices": [], "desc": "Mechanically speaking, an opponent is typically reduced to three numbers: Skill, Stamina, and Initiative. Beyond this they may have an Advanced Skill or two or some peculiar special rules.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tgi5ZmozeCtBsJEZYvhiVYH", "key": "Enemies", "name": "Enemies", "parent": "#tMhLXyRX3bWMDKiGwMvtZ3C", "props": [{"name": "Number", "type": "STRING", "value": "7.2", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Enemies", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tgm9giBHXoDyzHbATMn2uAm": {"book": "rules", "children": [], "choices": [], "desc": "In the case of a tie the character may Test their Luck to break it in their favour. When a character successfully hits an opponent, but before rolling for Damage, they may decide to Test their Luck and, if successful, may add 2 to their Damage Roll.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tgm9giBHXoDyzHbATMn2uAm", "key": "Use of Luck in Combat", "name": "Use of Luck in Combat", "parent": "#tTHvq23nxz31IzPMzISJMli", "props": [{"name": "Number", "type": "STRING", "value": "3.3", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Use of Luck in Combat", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#thqEo9kFRhzbsU81hlfEVhc": {"book": "rules", "children": ["#tk2sWf6d1YqTzvX7lhfg4S0", "#tYmlzHezIsyLzw3LwFmvZHi", "#tR5pGMhUsua6OgkJgaklYDB", "#tCHoWNZtcmCFV7MB5C9KBuk", "#tV9P8EMQglefTupJK4PvN7j", "#tlkeDzjf3PHzDtQbAq3AEmi", "#tdLHSrDDxqhgKWUgb6NEUAW", "#tjnSB49n4i9QerepL8w655s"], "choices": [], "desc": "When you hold the Initiative you may take a Turn and can generally perform one action. The following list is not exhaustive and the GM is encouraged to interpret player intentions as best they can.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#thqEo9kFRhzbsU81hlfEVhc", "key": "Actions", "name": "Actions", "parent": null, "props": [{"name": "Number", "type": "STRING", "value": "6", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Actions", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tiznrZZF7r4PK0hfUD6SW6m": {"book": "rules", "children": [], "choices": [], "desc": "Add 1 Token of a distinct colour to the Stack. This Token signifies the End of the Round.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tiznrZZF7r4PK0hfUD6SW6m", "key": "5.1.3", "name": "5.1.3", "parent": "#tJTqOdfo8T1KBFp6qdyKVyP", "props": [{"name": "Number", "type": "STRING", "value": "5.1.3", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tjXmW7rzBVnNpBNePD3LfSq": {"book": "rules", "children": [], "choices": [], "desc": "Degenerative Effects in Combat. Test for Drowning, fire, etc. only when the End of the Round Token is drawn.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tjXmW7rzBVnNpBNePD3LfSq", "key": "7.9.2", "name": "7.9.2", "parent": "#tmgNP1VdTufqKr7Y2wT6Xhg", "props": [{"name": "Number", "type": "STRING", "value": "7.9.2", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tjnSB49n4i9QerepL8w655s": {"book": "rules", "children": [], "choices": [], "desc": "Roll Versus your opponent’s Wrestling Skill. If you win you may either knock them to the ground or deal Damage as Unarmed and knock you both to the ground (from throwing or tackling them). On a Mighty Blow (7.4) you render them unconscious for 1d6 Rounds. If you fail to grapple them they may deal Damage to you as though they had attacked you normally whereas if you Fumble (7.5) they deal you a Mighty Blow.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tjnSB49n4i9QerepL8w655s", "key": "Grapple", "name": "Grapple", "parent": "#thqEo9kFRhzbsU81hlfEVhc", "props": [{"name": "Number", "type": "STRING", "value": "6.8", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Grapple", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tk2sWf6d1YqTzvX7lhfg4S0": {"book": "rules", "children": [], "choices": [], "desc": "To stab, bludgeon, or otherwise physically interfere with someone, Roll (2d6+Skill+Advanced Skill) Versus an opponent doing the same thing. The winner Rolls for Damage and the loser deducts the number generated by the Damage Roll from their Stamina. Note that either party in any exchange can potentially win. In a tie both parties have avoided hurting each other. Also note that this means you can potentially hit an unlimited number of people in a Round but may only Initiate once per Turn.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tk2sWf6d1YqTzvX7lhfg4S0", "key": "Hit Someone", "name": "Hit Someone", "parent": "#thqEo9kFRhzbsU81hlfEVhc", "props": [{"name": "Number", "type": "STRING", "value": "6.1", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Hit Someone", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tkmHPSvcRsQP4CeIdGS92X7": {"book": "rules", "children": [], "choices": [], "desc": "Falling Too Far. When engaging in uncontrolled falls you lose 1d6 Stamina per 2 metres fallen when you land.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tkmHPSvcRsQP4CeIdGS92X7", "key": "7.8.1", "name": "7.8.1", "parent": "#tQ0cdGbkIay6khBUwLP2hX5", "props": [{"name": "Number", "type": "STRING", "value": "7.8.1", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tlkeDzjf3PHzDtQbAq3AEmi": {"book": "rules", "children": [], "choices": [], "desc": "If you need to get something out that you weren’t already holding in your hands roll 2d6 and score equal to or higher than its position on your Inventory list. If you succeed you can pull it out and do what you intended. Otherwise you spend your entire action finding it. Double 1s always indicate a failure.\n\nRetrieving an arrow counts as an item retrieval. Make sure they’re packed on top! See Sections 10.3 and 10.4.1 for more on Inventories.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tlkeDzjf3PHzDtQbAq3AEmi", "key": "Retrieve an Item", "name": "Retrieve an Item", "parent": "#thqEo9kFRhzbsU81hlfEVhc", "props": [{"name": "Number", "type": "STRING", "value": "6.6", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Retrieve an Item", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tmgNP1VdTufqKr7Y2wT6Xhg": {"book": "rules", "children": ["#teAm2qHbWvT3WAenwFxKrdE", "#tjXmW7rzBVnNpBNePD3LfSq"], "choices": [], "desc": "When you fail a Swimming Test you begin to Drown and lose 1d6 Stamina. For each consecutive Swimming Test where you make no progress you roll an additional 1d6. So for instance your third failed Swimming roll in a row would lose you 3d6 Stamina. Once you lose all Stamina you have Drowned.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tmgNP1VdTufqKr7Y2wT6Xhg", "key": "Drowning", "name": "Drowning", "parent": "#tMhLXyRX3bWMDKiGwMvtZ3C", "props": [{"name": "Number", "type": "STRING", "value": "7.9", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Drowning", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tnFNK0CoHKAXKJ3QZRntBQS": {"book": "rules", "children": [], "choices": [], "desc": "Shooting Into Melee. When shooting into melee on a successful hit assign a number to every individual involved and roll a die. If their number comes up they receive the Damage.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tnFNK0CoHKAXKJ3QZRntBQS", "key": "6.2.1", "name": "6.2.1", "parent": "#tYmlzHezIsyLzw3LwFmvZHi", "props": [{"name": "Number", "type": "STRING", "value": "6.2.1", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#toanDbyX8nTLpiPNLhJKjgd": {"book": "rules", "children": [], "choices": [], "desc": "You may immediately make a new character while others mourn your loss and fight over your possessions. This new character starts exactly according to the rules found at the beginning of this book.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#toanDbyX8nTLpiPNLhJKjgd", "key": "Death", "name": "Death", "parent": "#tRawJw3bjpwBl1MGgwHThMN", "props": [{"name": "Number", "type": "STRING", "value": "4.4", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Death", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tp76Vl6mTXBfynA57DUxzPy": {"book": "rules", "children": ["#tJTqOdfo8T1KBFp6qdyKVyP", "#t9N2I7tsxT536igEoVRHKyz", "#tpfW5jgoumM1Xupgjfd5jPV", "#tODrM4gJZaT5y1yBldhg3Fy", "#tHaahA2NuBfgypvZHGd0Jd1", "#t8sT6YvwXwA26nT9Ag04Ach"], "choices": [], "desc": null, "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tp76Vl6mTXBfynA57DUxzPy", "key": "Initiative", "name": "Initiative", "parent": null, "props": [{"name": "Number", "type": "STRING", "value": "5", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Initiative", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tpfW5jgoumM1Xupgjfd5jPV": {"book": "rules", "children": [], "choices": [], "desc": "If the End of the Round Token is drawn all Tokens, including the End of the Round Token, are put back in the Stack. Remove Tokens contributed by dead characters and enemies, resolve any per Round or end of Round activities such as magic effects, Drowning (7.9), fire, poison, or bleeding, then draw another Token and carry on.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tpfW5jgoumM1Xupgjfd5jPV", "key": "End of the Round", "name": "End of the Round", "parent": "#tp76Vl6mTXBfynA57DUxzPy", "props": [{"name": "Number", "type": "STRING", "value": "5.3", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "End of the Round", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tqOgp3wMSJRuGiR00eEyCZh": {"book": "rules", "children": [], "choices": [], "desc": "Add Tokens to the Stack for the enemies equal to their total combined Initiative (if you have 8 Lizard-Men (Initiative 2) you would add 16 tokens to the Stack).", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tqOgp3wMSJRuGiR00eEyCZh", "key": "5.1.2", "name": "5.1.2", "parent": "#tJTqOdfo8T1KBFp6qdyKVyP", "props": [{"name": "Number", "type": "STRING", "value": "5.1.2", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tre5BJhC7N5xal6bKNrIDfG": {"book": "rules", "children": [], "choices": [], "desc": "When you successfully Test an Advanced Skill or Spell, put a tick next to it on your character sheet. These are used to Get Better (11.1).", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tre5BJhC7N5xal6bKNrIDfG", "key": "2.1.1", "name": "2.1.1", "parent": "#t8XyFUV2Bu5BdxKwKUPYfjl", "props": [{"name": "Number", "type": "STRING", "value": "2.1.1", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tshYslnHBIFqwvuUVarZsmJ": {"book": "rules", "children": [], "choices": [], "desc": "Dropping Things in a Hurry. If you want to unburden yourself quickly roll 1d6. The result is how many slots of things you may carefully put down this Turn. At the GM’s discretion you may roll 2d6 if you don’t mind them getting broken or lost.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tshYslnHBIFqwvuUVarZsmJ", "key": "10.4.1", "name": "10.4.1", "parent": "#tXH8O2PZSmgG9cLrbnDQN7a", "props": [{"name": "Number", "type": "STRING", "value": "10.4.1", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#ttkbj9neGS6PF9v9iKUNYYM": {"book": "rules", "children": [], "choices": [], "desc": "Henchmen are created as you would a monster, with truncated abilities only covering their essence. They are their own people with their own motivations and are not just pieces of equipment. It is up to the GM and players to flesh them out or not as the case may be. Also see Section 5.4.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#ttkbj9neGS6PF9v9iKUNYYM", "key": "Henchmen", "name": "Henchmen", "parent": "#tMhLXyRX3bWMDKiGwMvtZ3C", "props": [{"name": "Number", "type": "STRING", "value": "7.10", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Henchmen", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tuZl4biz8GWTQEAC7fKPIXY": {"book": "rules", "children": [], "choices": [], "desc": "When attacking someone in cover they receive a bonus to their roll to not be hit. Consider a waist high bush to be +1 while a castle’s crenulations would be +6.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tuZl4biz8GWTQEAC7fKPIXY", "key": "Cover", "name": "Cover", "parent": "#tMhLXyRX3bWMDKiGwMvtZ3C", "props": [{"name": "Number", "type": "STRING", "value": "7.1", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Cover", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tuq3Gag3c2OWVuQsQV1pM1s": {"book": "rules", "children": [], "choices": [], "desc": "OPTIONAL: Enemy Initiative Limit. It is very likely that sometimes the characters’ enemies grossly outnumber them, and make it very hard for them to act. The GM may optionally limit the number of Enemy Initiative Tokens placed in the Stack to double that which the characters contribute. So if a party of 5 (10 Initiative Tokens in total) is attacked by fifty goblins (50 Initiative Tokens) the goblins only contribute 20 Tokens to the Stack. Bear in mind that the GM should feel free to balance Initiative Stacks as it seems appropriate.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tuq3Gag3c2OWVuQsQV1pM1s", "key": "5.1.4", "name": "5.1.4", "parent": "#tJTqOdfo8T1KBFp6qdyKVyP", "props": [{"name": "Number", "type": "STRING", "value": "5.1.4", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tvY0qW9xActloLVo5kOBhrv": {"book": "rules", "children": [], "choices": [], "desc": "When striking a Mighty Blow (7.4) you double the amount of Stamina lost as a result of a Damage Roll.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tvY0qW9xActloLVo5kOBhrv", "key": "Double Damage", "name": "Double Damage", "parent": "#tXGhNyPKBpHwLvFDYnn1mMx", "props": [{"name": "Number", "type": "STRING", "value": "8.1", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Double Damage", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tzfs8UbA9xaGFSk36Zq8Y4x": {"book": "rules", "children": [], "choices": [], "desc": "Roll Versus, mostly used for combat or other contests, occurs when two opponents each roll 2d6, add any applicable bonuses, then compare results, the higher total winning. In a duel you might be rolling 2d6 plus your Sword Fighting total, looking to beat your opponent who is doing similar.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tzfs8UbA9xaGFSk36Zq8Y4x", "key": "Roll Versus", "name": "Roll Versus", "parent": "#tV6ZYqFoGLyDVPSyrCVU92t", "props": [{"name": "Number", "type": "STRING", "value": "1.2", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Roll Versus", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}, "#tzk4S4CWYL7177wKNptu87Z": {"book": "rules", "children": [], "choices": [], "desc": "When rolling Damage you may choose which Weapon to reference the Damage Roll against after rolling. You must be holding it in your hands or nearest approximations, obviously.", "entries": [], "file": "troika-0.5-core-rules.ttrpg", "form": "DEF", "guidance": [], "id": "#tzk4S4CWYL7177wKNptu87Z", "key": "Use of Multiple Weapons", "name": "Use of Multiple Weapons", "parent": "#tMhLXyRX3bWMDKiGwMvtZ3C", "props": [{"name": "Number", "type": "STRING", "value": "7.7", "vk": "scalar"}, {"name": "Title", "type": "STRING", "value": "Use of Multiple Weapons", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Rule", "typeHash": "#tro5Rule00000000001"}}, "src": "data/rules.js"};var T=window.TROIKA=window.TROIKA||{books:{},entities:{},loaded:{}};
T.loaded[d.src]=true;T.books[d.book.id]=d.book;
for(var h in d.entities){T.entities[h]=d.entities[h];}})();
